package com.modelgate.platform.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.modelgate.platform.dto.ProviderRegisterRequest;
import com.modelgate.platform.entity.ModelProvider;
import com.modelgate.platform.entity.User;
import com.modelgate.platform.mapper.ModelProviderMapper;
import com.modelgate.platform.mapper.UserMapper;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Service;

@Service
public class ProviderService {
    private static final int HTTP_TIMEOUT_MILLIS = 10_000;

    private final ModelProviderMapper providerMapper;
    private final UserMapper userMapper;
    private final ObjectMapper objectMapper;

    public ProviderService(ModelProviderMapper providerMapper, UserMapper userMapper,
                           ObjectMapper objectMapper) {
        this.providerMapper = providerMapper;
        this.userMapper = userMapper;
        this.objectMapper = objectMapper;
    }

    public ModelProvider register(String username, ProviderRegisterRequest request) {
        User user = userMapper.findByUsername(username);
        if (user == null) {
            throw new IllegalArgumentException("Authenticated user does not exist");
        }
        ModelProvider provider = ModelProvider.builder()
                .userId(user.getId())
                .name(request.getName())
                .baseUrl(request.getBaseUrl())
                .apiKey(request.getApiKey())
                .modelId(request.getModelId())
                .status("PENDING")
                .errorMessage(null)
                .lastValidatedAt(null)
                .createdAt(LocalDateTime.now())
                .build();
        providerMapper.insert(provider);
        return provider;
    }

    public ModelProvider validate(Long id, String username) {
        ModelProvider provider = findOwned(id, username);
        if (provider == null) {
            return null;
        }

        try {
            Integer phaseOneStatus = request(
                    appendPath(provider.getBaseUrl(), "/models/" + provider.getModelId()),
                    "GET", provider.getApiKey(), null);
            if (phaseOneStatus != null && (phaseOneStatus == 401 || phaseOneStatus == 403)) {
                setInvalid(provider, phaseOneStatus);
            } else if (phaseOneStatus == null || phaseOneStatus == 404) {
                Map<String, Object> userMessage = new LinkedHashMap<>();
                userMessage.put("role", "user");
                userMessage.put("content", "Hi");
                Map<String, Object> probe = new LinkedHashMap<>();
                probe.put("model", provider.getModelId());
                probe.put("messages", Collections.singletonList(userMessage));
                probe.put("max_tokens", 1);

                Integer phaseTwoStatus = request(
                        appendPath(provider.getBaseUrl(), "/v1/chat/completions"),
                        "POST", provider.getApiKey(), objectMapper.writeValueAsBytes(probe));
                if (phaseTwoStatus == null) {
                    provider.setStatus("ERROR");
                    provider.setErrorMessage("Connection failed");
                } else if (phaseTwoStatus == 401 || phaseTwoStatus == 403) {
                    setInvalid(provider, phaseTwoStatus);
                } else {
                    setValid(provider);
                }
            } else {
                setValid(provider);
            }
        } catch (Exception exception) {
            provider.setStatus("ERROR");
            provider.setErrorMessage(exception.getMessage());
        }

        provider.setLastValidatedAt(LocalDateTime.now());
        providerMapper.update(provider);
        return provider;
    }

    public List<ModelProvider> findAllForUser(String username) {
        User user = userMapper.findByUsername(username);
        return user == null ? Collections.emptyList() : providerMapper.findByUserId(user.getId());
    }

    public ModelProvider findOwned(Long id, String username) {
        User user = userMapper.findByUsername(username);
        if (user == null) {
            return null;
        }
        ModelProvider provider = providerMapper.findById(id);
        if (provider == null || !user.getId().equals(provider.getUserId())) {
            return null;
        }
        return provider;
    }

    private Integer request(String target, String method, String apiKey, byte[] body) {
        HttpURLConnection connection = null;
        try {
            connection = (HttpURLConnection) new URL(target).openConnection();
            connection.setRequestMethod(method);
            connection.setConnectTimeout(HTTP_TIMEOUT_MILLIS);
            connection.setReadTimeout(HTTP_TIMEOUT_MILLIS);
            connection.setRequestProperty("Authorization", "Bearer " + apiKey);
            if (body != null) {
                connection.setRequestProperty("Content-Type", "application/json");
                connection.setDoOutput(true);
                try (OutputStream output = connection.getOutputStream()) {
                    output.write(body);
                }
            }
            return connection.getResponseCode();
        } catch (Exception exception) {
            return null;
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private static String appendPath(String baseUrl, String path) {
        if (baseUrl.endsWith("/") && path.startsWith("/")) {
            return baseUrl.substring(0, baseUrl.length() - 1) + path;
        }
        return baseUrl + path;
    }

    private static void setInvalid(ModelProvider provider, int status) {
        provider.setStatus("INVALID");
        provider.setErrorMessage("API key is invalid (HTTP " + status + ")");
    }

    private static void setValid(ModelProvider provider) {
        provider.setStatus("VALID");
        provider.setErrorMessage(null);
    }
}

